import pytest

SKILL_DIR = Path(__file__).parent.parent
AUDIO_PROCESSOR = SKILL_DIR / "movie_project" / "tools" / "audio_processor.py"


def _run_audio_processor(args: list[str]) -> subprocess.CompletedProcess[str]:
    return subprocess.run(
        [sys.executable, str(AUDIO_PROCESSOR), *args],
        capture_output=True,
        text=True,
    )


class TestAudioProcessor:
    def test_dry_run_requires_input(self, tmp_path: Path):
        if not AUDIO_PROCESSOR.exists():
            pytest.skip("audio_processor tool not found")

        output = tmp_path / "out.m4a"
