    def test_dry_run_with_voice(self, tmp_path: Path):
        if not AUDIO_PROCESSOR.exists():
            pytest.skip("audio_processor tool not found")

        voice = tmp_path / "voice.wav"
        voice.write_bytes(b"")
        output = tmp_path / "mix.m4a"

        result = _run_audio_processor([
            "--dry-run",
            "--voice", str(voice),
            "--output", str(output),
        ])
        assert result.returncode == 0
        assert "DRY RUN" in result.stdout
